        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        int t = 0;
        for (int[] c : courses) {
            pq.add(c[0]);
            t += c[0];
            if (t > c[1]) t -= pq.poll();
        }
        return pq.size();
